"use client";
import * as React from "react";
import { cn } from "../lib/cn";

export interface DataPillProps extends React.HTMLAttributes<HTMLSpanElement> {
  label: React.ReactNode;
  value: React.ReactNode;
  /** Eenheid achter de waarde, bv. "mmHg" of "µm". */
  unit?: React.ReactNode;
  icon?: React.ReactNode;
  tone?: "neutral" | "accent" | "green" | "amber" | "red" | "blue" | "violet";
  size?: "sm" | "md";
}

/** DataPill — compacte meetwaarde: label, waarde en eenheid op één regel. */
export const DataPill = React.forwardRef<HTMLSpanElement, DataPillProps>(function DataPill(
  { label, value, unit, icon, tone = "neutral", size = "md", className, ...rest },
  ref
) {
  return (
    <span
      ref={ref}
      className={cn("lui-datapill", `lui-datapill-${tone}`, `lui-datapill-${size}`, className)}
      {...rest}
    >
      {icon && <span className="lui-datapill-icon">{icon}</span>}
      <span className="lui-datapill-label">{label}</span>
      <b className="lui-datapill-value">{value}</b>
      {unit && <em className="lui-datapill-unit">{unit}</em>}
    </span>
  );
});

/* ============================ DataPill ============================ */
.lui-datapill {
  --lui-pill-color: var(--text-3);
  display: inline-flex; align-items: baseline; gap: 6px;
  padding: 5px 11px; border-radius: var(--r-full);
  background: var(--surface-2); border: 1px solid var(--border);
  font-size: 12px; color: var(--text-3); white-space: nowrap;
}
.lui-datapill-icon { display: inline-flex; align-self: center; color: var(--lui-pill-color); }
.lui-datapill-icon svg { width: 14px; height: 14px; }
.lui-datapill-label { font-weight: 600; }
.lui-datapill-value {
  font-size: 13px; font-weight: 700; color: var(--text);
  font-variant-numeric: tabular-nums;
}
.lui-datapill-unit { font-style: normal; font-size: 11px; color: var(--text-3); }

.lui-datapill-sm { padding: 3px 8px; font-size: 11px; }
.lui-datapill-sm .lui-datapill-value { font-size: 12px; }

.lui-datapill-accent { --lui-pill-color: var(--accent); background: var(--accent-tint); border-color: var(--accent-border); }
.lui-datapill-green { --lui-pill-color: var(--green); background: var(--green-tint); border-color: var(--green-border); }
.lui-datapill-amber { --lui-pill-color: var(--amber); background: var(--amber-tint); border-color: var(--amber-border); }
.lui-datapill-red { --lui-pill-color: var(--red); background: var(--red-tint); border-color: var(--red-border); }
.lui-datapill-blue { --lui-pill-color: var(--blue); background: var(--blue-tint); border-color: var(--blue-border); }
.lui-datapill-violet { --lui-pill-color: var(--violet); background: var(--violet-tint); border-color: var(--violet-border); }
